entries[44141] = { ["name"] = "Saat der Verderbnis", ["text"] = "550 Mana 30 Meter Reichweite\nWirken in 2 sek.\nPflanzt dem feindlichen Ziel eine Saat der Verderbnis ein, die im Verlauf von 18 Sek. (100.2% der Zaubermacht) Schattenschaden verursacht. Wenn das Ziel insgesamt 2500 Schaden erleidet, detoniert die Saat und fügt allen Feinden im Umkreis von 10 Metern um das Ziel Schattenschaden zu." }
