entries[44151] = { ["name"] = "Turbogetriebene Flugmaschine", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine turbogetriebene Flugmaschine oder gibt sie wieder frei. Benötigt 75 Fertigkeitspunkte in der Ingenieurskunst der Scherbenwelt. Diese Flugmaschine passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Nur die talentiertesten Ingenieure verfügen über den Mut und die geistige Ausdauer, um eine Flugmaschine zu bauen, die derartige Stabilität und Sicherheit bietet. Sie mit einem Turbo anzutreiben, ist einfach nur Irrsinn!\"\nBeruf:\nIngenieurskunst" }
entries[44152] = { ["name"] = "Steinriesen bezaubern" }
entries[44153] = { ["name"] = "Flugmaschine", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine Flugmaschine oder gibt sie wieder frei. Benötigt 1 Fertigkeitspunkt in der Ingenieurskunst der Scherbenwelt. Diese Flugmaschine passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Das Rückgrat der Luftstreitkräfte der Allianz besteht aufgrund ihrer Manövrierfähigkeit und Geschwindigkeit größtenteils aus gnomischen Flugmaschinen.\"\nBeruf:\nIngenieurskunst" }
entries[44155] = { ["name"] = "Flugmaschine", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nTeufelseisengehäuse (2), Elementarsprengpulver (20), Eine Handvoll Teufelseisenbolzen (20), Sternenholz (8)\nEine unglaubliche Maschine, die es dem Ingenieur ermöglicht, zu fliegen.\nBerufsausbilder:\nIngenieurskunst der Scherbenwelt (1)\nKosten:\n10\n\nFlugmaschine\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine Flugmaschine oder gibt sie wieder frei. Benötigt 1 Fertigkeitspunkt in der Ingenieurskunst der Scherbenwelt. Diese Flugmaschine passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Ingenieurskunst der Scherbenwelt\n(1)\nBenötigt Unerfahrenes Reiten\n\n\"Das Rückgrat der Luftstreitkräfte der Allianz besteht aufgrund ihrer Manövrierfähigkeit und Geschwindigkeit größtenteils aus gnomischen Flugmaschinen.\"\nBeruf:\nIngenieurskunst" }
entries[44156] = { ["name"] = "Pring Master" }
entries[44157] = { ["name"] = "Turbogetriebene Flugmaschine", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nAdamantitrahmen (4), Khoriumkraftkern (8), Teufelsstahlstabilisator (8), Hula-Wackelpuppe\nEine unglaubliche Maschine, die es dem Ingenieur ermöglicht, zu fliegen. Dieses Modell ist turbogetrieben.\nBerufsausbilder:\nIngenieurskunst der Scherbenwelt (75)\nKosten:\n3\n50\n\nTurbogetriebene Flugmaschine\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine turbogetriebene Flugmaschine oder gibt sie wieder frei. Benötigt 75 Fertigkeitspunkte in der Ingenieurskunst der Scherbenwelt. Diese Flugmaschine passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Ingenieurskunst der Scherbenwelt\n(75)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die talentiertesten Ingenieure verfügen über den Mut und die geistige Ausdauer, um eine Flugmaschine zu bauen, die derartige Stabilität und Sicherheit bietet. Sie mit einem Turbo anzutreiben, ist einfach nur Irrsinn!\"\nBeruf:\nIngenieurskunst" }
